import {supportCatalog} from './support-catalog.js';
import {careFor,puppyCare} from './care-knowledge.js';
export const SUPPORT_REVISION='0.4.0';
export const salonFacts={name:'МиМиРум',address:'Санкт-Петербург, Пулковское шоссе, 14, стр. 6',entrance:'между Tabacco и Яндекс Маркетом',hours:'Ежедневно 10:00–21:00, по предварительной записи',phone:'+7 (950) 040-44-29',phoneLink:'tel:+79500404429',website:'https://mimi-room.ru',catalogDate:'2026-11-07',offer:'Дневная скидка 5% на комплекс с началом в понедельник, вторник или среду с 11:00 до 14:00 включительно при самостоятельном приезде. С бесплатной доставкой, другими скидками, доплатами и отдельными услугами не суммируется. Условия и визит подтверждает салон.'};
const norm=s=>String(s??'').toLowerCase().replaceAll('ё','е').replace(/[^a-zа-я0-9\s.,-]/g,' ').replace(/\s+/g,' ').trim();
export function redactContacts(s){return String(s).replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi,'[email скрыт]').replace(/(?:\+?7|8)[\s()-]*\d(?:[\s()-]*\d){9}\b/g,'[телефон скрыт]').slice(0,1600)}
const aliases=[['DOG-AMERICAN-BULLY',/американск[а-я]*\s+бул(?!ь?терьер|ь?дог)[а-я]*|\bamerican bully\b|булли|буллей/],['DOG-BULL-TERRIER',/бультерьер|минибуль|bull terrier/],['DOG-PITBULL',/пит.?бул|pitbull/],['DOG-AMSTAFF',/амстафф|стаффорд|amstaff/],['DOG-MALTIPOO',/мальтип|малтип|maltipoo|мальти пу/],['DOG-YORK',/йорк|york/],['DOG-POMERANIAN',/шпиц|померан|pomeranian/],['DOG-BICHON',/бишон|bichon/],['DOG-POODLE',/пудел|пудл|poodle/],['DOG-CORGI',/корги|corgi/],['CAT-MAINECOON',/мейн.?кун|maine.?coon/],['CAT-BRITISH',/британ/],['CAT-SCOTTISH',/шотланд/],['CAT-SPHYNX',/сфинкс/],['DOG-SHIHTZU',/ши.?тцу/],['DOG-CHIHUAHUA',/чихуа/],['DOG-SHIBA-INU',/сиба|шиба/],['DOG-AUSSIE',/аусси|австралийск.*овчарк/],['DOG-BEAGLE',/бигл/],['DOG-PUG',/мопс/],['DOG-DOBERMAN',/доберман/],['DOG-ALABAI',/алаба/],['DOG-DACHSHUND',/такс(?:а|у|ой|е|ы|ами)(?=\s|$)/],['DOG-SCHNAUZER',/шнауцер/],['DOG-SHEPHERD',/немецк[а-я]*.*овчарк/],['DOG-JACKRUSSELL',/джек.*рассел/],['DOG-COCKER',/кокер|спаниел/],['CAT-BENGAL',/бенгал/],['CAT-SIAMESE',/сиам/],['DOG-BULLDOG',/английск[а-я]*.*бульдог/],['DOG-LABRADOR',/лабрадор/],['DOG-AKITA-INU',/акит/],['DOG-MINIATURE-PINSCHER',/цвергпинчер|миниатюрн[а-я]*.*пинчер/],['DOG-GERMAN-PINSCHER',/немецк[а-я]*.*пинчер/],['DOG-BORDER-COLLIE',/бордер.*колли/]];
const byId=id=>supportCatalog.find(s=>s.id===id);
export function matchBreed(text){const q=norm(text);const alias=aliases.find(([,re])=>re.test(q));if(alias)return {id:alias[0],soft:false};let best=null;for(const s of supportCatalog.filter(s=>s.group==='breeds'&&!s.id.endsWith('-ALL'))){const name=norm(s.title.split('—').slice(1).join(' '));if(name&&q.includes(name)&&(!best||name.length>best.length))best={id:s.id,length:name.length,soft:false}}return best}
const weightIn=q=>{const m=/(\d{1,3}(?:[.,]\d+)?)\s*(?:кг|килограмм[а-я]*)(?=\s|[.,!?]|$)/u.exec(q);return m&&Number(m[1].replace(',','.'))>0?Number(m[1].replace(',','.')):null};
const ageIn=q=>{const m=/(\d{1,2}(?:[.,]\d+)?)\s*(месяц[а-я]*|мес\.?|лет|год[а-я]*|недел[а-я]*)/u.exec(q);return m?{value:Number(m[1].replace(',','.')),unit:m[2],months:Number(m[1].replace(',','.'))*(/лет|год/.test(m[2])?12:/недел/.test(m[2])?0.23:1)}:null};
export function conversationProfile(message,history=[],remembered=null){let p={breedId:null,softBreed:false,weight:null,age:null,newOwner:false,firstVisit:null,skin:null,tolerance:null};const saved=remembered&&byId(remembered.breedId)?remembered:null;if(saved){p={...p,breedId:saved.breedId,softBreed:false,weight:Number(saved.weight)>0&&Number(saved.weight)<300?Number(saved.weight):null,age:saved.age&&Number(saved.age.months)>0&&Number(saved.age.months)<600?{value:Number(saved.age.value)||Number(saved.age.months),months:Number(saved.age.months),unit:String(saved.age.unit||'мес').slice(0,12)}:null,newOwner:saved.newOwner===true,firstVisit:typeof saved.firstVisit==='boolean'?saved.firstVisit:null,skin:saved.skin==='clear'?'clear':null,tolerance:['calm','anxious'].includes(saved.tolerance)?saved.tolerance:null}}for(const text of [...(saved?[]:history).filter(h=>h?.role==='user'&&typeof h.content==='string').slice(-12).map(h=>h.content),message]){const q=norm(text),b=matchBreed(q);if(b&&b.id!==p.breedId)p={breedId:b.id,softBreed:b.soft,weight:null,age:null,newOwner:false,firstVisit:null,skin:null,tolerance:null};else if(b)p.softBreed=b.soft;const weight=weightIn(q),age=ageIn(q);if(weight)p.weight=weight;if(age)p.age=age;if(/только купил|только взял|перв[а-я]*\s+собак|ничего не знаю|впервые.*питом/.test(q))p.newOwner=true;if(/перв[а-я]*\s+(?:раз|визит)|ни разу|не был[аи]?\s+у грумер/.test(q))p.firstVisit=true;if(/уже (?:были|ходили)|не первый/.test(q))p.firstVisit=false;if(/нет (?:раздраж|зуда|покрасн)|без (?:раздраж|зуда|покрасн)|кожа (?:чистая|нормальная)/.test(q))p.skin='clear';if(/не боится|спокойно.*(?:вод|фен)|любит воду/.test(q))p.tolerance='calm';if(/боится|не любит.*(?:вод|фен)/.test(q)&&!/не боится/.test(q))p.tolerance='anxious'}return p}
export function priceText(s){return /Цена:\s*([^]+?)(?:Продолжительность:|Условия:|$)/i.exec(s.description)?.[1]?.trim()||s.priceLabel||`от ${Number(s.price).toLocaleString('ru-RU')} ₽`}
export function includedText(s){const d=s.description.split('Цена:')[0].trim();return d.replace(/^Вес:[^.]+\.\s*/,'')}
function tariffFor(s,weight){if(!weight)return null;for(const part of priceText(s).split(';')){const value=/—\s*([\d\s]+)\s*₽/.exec(part);if(!value)continue;const range=/(?:свыше|более)\s+(\d+(?:[.,]\d+)?)\s+до\s+(\d+(?:[.,]\d+)?)\s*кг/.exec(part)||/(\d+(?:[.,]\d+)?)\s*[–-]\s*(\d+(?:[.,]\d+)?)\s*кг/.exec(part);const upper=/до\s+(\d+(?:[.,]\d+)?)\s*кг/.exec(part);const lower=/(?:свыше|более)\s+(\d+(?:[.,]\d+)?)\s*кг/.exec(part);const n=v=>Number(v.replace(',','.'));if(range&&weight>n(range[1])&&weight<=n(range[2])||!range&&upper&&weight<=n(upper[1])||!range&&!upper&&lower&&weight>n(lower[1]))return value[1].trim()+' ₽'}return null}
function questionsFor(p){const q=[];if(p.softBreed)q.push('Правильно поняла, речь об американском булли?');if(!p.age&&!p.weight)q.push('Сколько ему месяцев или лет и примерно сколько он весит?');else if(!p.age)q.push('Сколько ему месяцев или лет?');else if(!p.weight)q.push('Какой у него примерно вес?');if(q.length<2&&p.firstVisit===null)q.push(p.tolerance?'Он уже был у грумера или начнём с первого знакомства?':'Он уже был у грумера и как относится к воде, фену и прикосновениям к лапам?');if(q.length<2&&p.age&&p.weight&&p.skin===null)q.push('Есть ли зуд, покраснение или известные реакции на косметику?');if(!q.length)q.push('Что сейчас беспокоит больше: линька, запах, загрязнение шерсти или нужен плановый уход?');return q.slice(0,2)}
function positiveSymptoms(q){const symptom='(?:зуд[а-я]*|покрасн[а-я]*|раздраж[а-я]*|ран[а-я]*|бол[ьи]|сып[а-я]*)';let clean=q.replace(new RegExp('(?:нет|без)\\s+(?:никаких\\s+)?'+symptom+'(?:\\s*(?:и|,|или)\\s*'+symptom+')*','g'),'').replace(new RegExp(symptom+'\\s*(?:у него\\s*)?(?:нет|отсутствуют|отсутствует)','g'),'').replace(/(?:ничего )?не болит/g,'');return /кровотеч|судорог|задыха|отрав|рвот|болит|порез|открыт[а-я]*\s+ран|сильн[а-я]*\s+зуд|покрасн|сыпь|воспален/.test(clean)}

export function buildSupportPlan(message,history=[],remembered=null){
 const q=norm(message),profile=conversationProfile(message,history,remembered),service=byId(profile.breedId),care=careFor(service),questions=questionsFor(profile);
 const base={mode:'reference',sources:[],handoff:false,reason:'',actions:['booking','human'],knowledgeDate:salonFacts.catalogDate,revision:SUPPORT_REVISION,profile,questions};
 if(/администратор|оператор|живой человек|позовите человека|хочу.*человеком/.test(q))return {...base,intent:'human',handoff:true,reason:'human',answer:'Конечно, можно поговорить с администратором. Нажмите «Связаться с администратором» внизу чата. Если удобнее позвонить: '+salonFacts.phone+'.'};
 if(/жалоб|возврат|верните деньги|претензи|травм/.test(q))return {...base,intent:'complaint',handoff:true,reason:'complaint',answer:'Понимаю, это нужно обсудить лично с администратором. Нажмите «Связаться с администратором» или позвоните '+salonFacts.phone+'. Я не могу самостоятельно принять решение по возврату.'};
 if(positiveSymptoms(q)||/наркоз|лекарств|диагноз|чем лечить|назнач.*леч/.test(q))return {...base,intent:'health',handoff:true,reason:'health',answer:'При таких симптомах сначала лучше обратиться к ветеринарному врачу, а косметический уход согласовать после оценки состояния кожи и здоровья. Я не ставлю диагнозы и не назначаю лечение. Администратор поможет обсудить перенос или спокойный формат визита; при остром ухудшении нужна ветеринарная помощь.'};
 if(/игнорируй|ignore previous|системн.*промпт|раскрой.*инструкц|придумай.*цен|бесплатно.*все|скидк.*100/.test(q))return {...base,intent:'guard',answer:'Помогу по реальному прайсу и уходу за питомцем. '+questions.join(' ')};
 const isIncluded=/что\s+(?:именно\s+)?входит|состав.*(?:уход|комплекс)|включ[а-я]*\s+в\s+(?:уход|комплекс)|что.*делаете|как.*(?:происходит|проходит|делают)|что с ним (?:сделать|делать)/.test(q);
 const isHome=/как.*ухаж|дом[ао]|между визит|сам(?:ому|ой|остоятельно)|щетк|расчес|шампун|как часто|чем (?:мыть|купать)|первый.*питом|ничего не знаю/.test(q);
 const isPrice=/сколько|стоит|стоимост|цен[ауы]|прайс|тариф/.test(q);
 if(!isIncluded&&!isHome&&/(?:^|\s)(?:где|адрес)(?:\s|$)|как (?:к вам )?добраться|где.*наход|как найти|(?:^|\s)вход(?:\s|$)|парков/.test(q))return {...base,intent:'location',answer:`Мы находимся: ${salonFacts.address}. Вход ${salonFacts.entrance}. ${salonFacts.hours}. По парковке и деталям подъезда поможет администратор.`};
 if(!isIncluded&&!isHome&&/время работ|график работ|до сколь|во сколько.*откры|когда.*работаете|как вы работаете|режим работ/.test(q))return {...base,intent:'hours',answer:salonFacts.hours+'. Записаться можно через выбор окошка; в чате я не подтверждаю бронь.'};
 if(/скидк|акци|бесплатн.*достав/.test(q))return {...base,intent:'offer',answer:salonFacts.offer+' Альтернатива: бесплатная доставка от двери и обратно с комплексным уходом в радиусе 10 км после подтверждения адреса и времени.',sources:[byId('SERVICE-TAXI-COMPLEX-FREE')]};
 if(/запиш|записа|свободн.*(?:врем|окош)|заброни/.test(q)&&!isPrice&&!isIncluded&&!isHome)return {...base,intent:'booking',answer:'Чтобы записаться, нажмите «Выбрать окошко»: там выбираются питомец, уход, мастер и время. Я не подтверждаю запись и не вижу актуальную занятость мастеров. '+(!profile.weight?'Для подбора ухода подскажите породу и вес питомца.':'')};
 let selected=[];
 if(/когт|когот/.test(q)&&!isIncluded&&!isHome)selected=[byId(/шлиф/.test(q)?'HYG-NAILS-GRIND':'HYG-NAILS-CLIP')];
 else if(/колтун|сваляв/.test(q)&&!service)selected=[byId('ADD-MATS')];
 else if(/достав|такси|забер|привез/.test(q)&&!isHome)selected=[byId('SERVICE-TAXI-COMPLEX-FREE'),byId('SERVICE-TAXI-NEIGHBOR')];
 else if(/передерж|ночев|прожив/.test(q))selected=/кошк|кот/.test(q)?[byId('SERVICE-BOARDING-CAT')]:[byId('SERVICE-BOARDING-DOG-S'),byId('SERVICE-BOARDING-DOG-M'),byId('SERVICE-BOARDING-DOG-L')];
 else if(/гигиен/.test(q)&&!isIncluded&&!isHome){const w=profile.weight,cat=/кош|кот/.test(q)||service?.pet==='cats';if(!w)return {...base,intent:'clarify',answer:'Подскажите, это кошка или собака и какой у питомца вес? Тогда назову подходящую категорию гигиенического комплекса.'};selected=[byId(cat?w<=5?'HYG-CAT-00-05':w<=8?'HYG-CAT-05-08':'HYG-CAT-08PLUS':w<=5?'HYG-DOG-00-05':w<=10?'HYG-DOG-05-10':w<=20?'HYG-DOG-10-20':w<=30?'HYG-DOG-20-30':w<=40?'HYG-DOG-30-40':'HYG-DOG-40PLUS')]}
 else if(service)selected=[service];
 selected=selected.filter(Boolean);
 if(!service&&!selected.length){const ambiguous=/(?:^|\s)бул(?:ем|ь|я|ю|ей|ле[йя])(?:\s|$)/.test(q);return {...base,intent:'clarify',answer:ambiguous?'Уточните, пожалуйста: американский булли, бультерьер или бульдог? Для них разный уход и прайс. Какой возраст и вес у питомца?':(!q||/привет|здравств|добрый/.test(q)?'Здравствуйте! ':'')+'Помогу разобраться и спокойно подобрать уход. Какая порода у питомца, сколько ему месяцев или лет и какой примерно вес?'}}
 const chosen=selected[0],sameBreed=chosen.id===service?.id,guide=careFor(chosen),newOwnerNow=/только купил|только взял|перв[а-я]*\s+собак|ничего не знаю/.test(q),profileReply=!matchBreed(q)&&Boolean(weightIn(q)||ageIn(q)),wantCare=isIncluded||isHome||newOwnerNow||!isPrice&&!profileReply;
 const exactPrice=tariffFor(chosen,profile.weight);const priceBlock=chosen.title+'\n'+(exactPrice?`При весе ${profile.weight} кг базовый ориентир — ${exactPrice}.`:priceText(chosen))+'\nИтоговую стоимость и дополнительные работы согласуем до начала ухода.';const blocks=[];
 if(newOwnerNow)blocks.push('Поздравляю с новым другом! Давайте разберёмся спокойно: сначала подберём уход под возраст, шерсть и привычки питомца.');
 if(sameBreed&&guide.kind==='short'&&!profileReply)blocks.push(guide.summary);
 if(wantCare)blocks.push('Как проходит уход в студии: '+includedText(chosen).split(/(?<=\.)\s+/).slice(0,2).join(' '));
 if(isPrice||!isIncluded&&!isHome){blocks.push(priceBlock);}
 if(isHome||newOwnerNow)blocks.push('Между визитами дома:\n'+guide.home.map(t=>'• '+t).join('\n'));
 if((profile.age&&profile.age.months<12||profile.firstVisit||profile.newOwner)&&(isHome||wantCare)&&!profileReply)blocks.push(puppyCare);
 blocks.push(questions.join(' '));
 const intent=isIncluded?'included':isHome?'care':'catalog';
 return {...base,intent,priceRequested:isPrice,priceBlock:isPrice||!isIncluded&&!isHome?priceBlock:null,expectedPrice:exactPrice,sources:selected,answer:blocks.join('\n\n'),care:guide,careSources:wantCare?guide.sources:[],context:{service:{id:chosen.id,title:chosen.title,price:priceText(chosen),included:includedText(chosen),duration:/Продолжительность:\s*([^]+?)(?:Условия:|$)/.exec(chosen.description)?.[1]?.trim()||null},home:guide.home,summary:guide.summary,avoid:guide.avoid,puppy:profile.age?.months<12||profile.newOwner?puppyCare:null,profile,questions,intent}};
}
export const sourceCard=s=>({id:s.id,title:s.title,price:s.price,priceLabel:s.priceLabel||'от '+Number(s.price).toLocaleString('ru-RU')+' ₽',description:s.description,source:salonFacts.website+'/#services'});
